// ── Markdown rendering ─────────────────────────────────────────────────────
import { marked } from 'marked';
import hljs from 'highlight.js/lib/core';

// Register common languages for markdown code blocks
import hljsJS         from 'highlight.js/lib/languages/javascript';
import hljsTS         from 'highlight.js/lib/languages/typescript';
import hljsPY         from 'highlight.js/lib/languages/python';
import hljsRust       from 'highlight.js/lib/languages/rust';
import hljsGo         from 'highlight.js/lib/languages/go';
import hljsJava       from 'highlight.js/lib/languages/java';
import hljsCpp        from 'highlight.js/lib/languages/cpp';
import hljsCS         from 'highlight.js/lib/languages/csharp';
import hljsRuby       from 'highlight.js/lib/languages/ruby';
import hljsPHP        from 'highlight.js/lib/languages/php';
import hljsShell      from 'highlight.js/lib/languages/bash';
import hljsSQL        from 'highlight.js/lib/languages/sql';
import hljsJSON       from 'highlight.js/lib/languages/json';
import hljsYAML       from 'highlight.js/lib/languages/yaml';
import hljsHTML       from 'highlight.js/lib/languages/xml';
import hljsCSS        from 'highlight.js/lib/languages/css';
import hljsScss       from 'highlight.js/lib/languages/scss';
import hljsKotlin     from 'highlight.js/lib/languages/kotlin';
import hljsSwift      from 'highlight.js/lib/languages/swift';
import hljsMarkdown   from 'highlight.js/lib/languages/markdown';
import hljsDiff       from 'highlight.js/lib/languages/diff';
import hljsIni        from 'highlight.js/lib/languages/ini';
import hljsMakefile   from 'highlight.js/lib/languages/makefile';
import hljsDocker     from 'highlight.js/lib/languages/dockerfile';

hljs.registerLanguage('javascript', hljsJS);
hljs.registerLanguage('js', hljsJS);
hljs.registerLanguage('typescript', hljsTS);
hljs.registerLanguage('ts', hljsTS);
hljs.registerLanguage('python', hljsPY);
hljs.registerLanguage('py', hljsPY);
hljs.registerLanguage('rust', hljsRust);
hljs.registerLanguage('rs', hljsRust);
hljs.registerLanguage('go', hljsGo);
hljs.registerLanguage('java', hljsJava);
hljs.registerLanguage('cpp', hljsCpp);
hljs.registerLanguage('c', hljsCpp);
hljs.registerLanguage('csharp', hljsCS);
hljs.registerLanguage('cs', hljsCS);
hljs.registerLanguage('ruby', hljsRuby);
hljs.registerLanguage('rb', hljsRuby);
hljs.registerLanguage('php', hljsPHP);
hljs.registerLanguage('bash', hljsShell);
hljs.registerLanguage('sh', hljsShell);
hljs.registerLanguage('shell', hljsShell);
hljs.registerLanguage('sql', hljsSQL);
hljs.registerLanguage('json', hljsJSON);
hljs.registerLanguage('yaml', hljsYAML);
hljs.registerLanguage('yml', hljsYAML);
hljs.registerLanguage('html', hljsHTML);
hljs.registerLanguage('xml', hljsHTML);
hljs.registerLanguage('css', hljsCSS);
hljs.registerLanguage('scss', hljsScss);
hljs.registerLanguage('kotlin', hljsKotlin);
hljs.registerLanguage('swift', hljsSwift);
hljs.registerLanguage('markdown', hljsMarkdown);
hljs.registerLanguage('md', hljsMarkdown);
hljs.registerLanguage('diff', hljsDiff);
hljs.registerLanguage('ini', hljsIni);
hljs.registerLanguage('makefile', hljsMakefile);
hljs.registerLanguage('dockerfile', hljsDocker);

// Export everything to the isolated world's globalThis
globalThis.ace    = ace;
globalThis.marked = marked;
globalThis.hljs   = hljs;
